INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (3,3,'["Pouvez-vous décrire concrètement un projet architectural ou d''aménagement que vous avez piloté de A à Z, en précisant votre rôle exact et les livrables produits ?", "Votre diplôme est en informatique, alors que le poste exige des compétences en architecture et gestion de projets : quelles formations complémentaires, certifications ou expériences terrain vous ont permis de combler cet écart ?", "Quels outils utilisez-vous pour la conception, le suivi et la coordination de projets architecturaux (BIM, AutoCAD, MS Project, etc.) et à quel niveau de maîtrise ?", "Comment gérez-vous la coordination entre les différents corps de métiers (architectes, ingénieurs, entreprises de travaux) sur un projet de grande envergure ?", "Sur vos 8 années d''expérience, dans quels secteurs d''activité avez-vous principalement exercé, et combien de ces années sont directement liées à des projets architecturaux ou urbains ?", "Avez-vous déjà travaillé dans un environnement régi par le Code des marchés publics marocain ou des procédures administratives similaires ? Si oui, dans quel cadre ?", "Qu''est-ce qui vous motive à rejoindre une agence de développement régional plutôt qu''un bureau d''études ou une entreprise privée dans votre domaine ?", "Où vous voyez-vous dans 5 ans, et en quoi ce poste à l''ADER s''inscrit-il dans votre trajectoire professionnelle ?", "Que savez-vous des missions et des projets structurants portés par l''ADER Fès-Meknès, et lequel vous interpelle le plus professionnellement ?", "Le secteur public impose des contraintes de délais, de budget et de redevabilité spécifiques : comment percevez-vous ces contraintes et comment y avez-vous fait face dans vos expériences passées ?"]','[]','{}','2026-08-27 13:25:57.361653') ON CONFLICT (id) DO NOTHING;